                ['url' => 'https://commons.wikimedia.org/wiki/File:Mountain_papaya_(Vasconcellea_pubescens).jpg', 'caption' => ['Buah carica atau pepaya gunung', 'Carica, the mountain papaya'], 'credit' => $commons],
